    "A": {
      "meta": {
        "code": "A",
        "label": "Pregnancy Registration (AD)"
      },
      "fields": {
        "patient_id": { "type": "string" },
        "lmp_date": { "type": "date" }
      }
    },
    "B": {
      "meta": {
        "code": "B",
        "label": "Pregnancy Registration (BS)"
      },
      "fields": {
        "patient_id": { "type": "string" },
